notes={176:'Effective/total stress separated; thick-ring and strip assumptions explicit.',177:'Hoisting and cutting capacities share in-situ basis only in the bottleneck comparison.',178:'Projection, wedge geometry and joint pressure remain explicit; area ratio is not a strength ratio.',179:'Thermal diffusion and outage reserve are scales, not permits. Thaw strain requires one-dimensional boundary.',180:'Slurry-water pressure difference is not total stability; high gradient is not an allowable gradient.',181:'Overlap and nominal geometry do not prove watertightness; independent errors are explicitly assumed.',182:'Euler/Rankine idealizations, dry-side water pressure and common datum are explicit.',183:'Thermal restraint, real contact and unloading stiffness boundaries are specified.',184:'Stable-zone geometry is distinguished from bond capacity; group efficiency is assumed.',185:'Steel-only stress, unsupported Euler segment, equal-displacement groups and connection moment couples are explicit.',186:'Dry-binder mass balance, unequal ground/column stress and dimensionless hydraulic gradient are separated; pressure head requires an added length.',187:'Equal-strain stiffness is distinguished from constrained modulus; rotations per metre are not mixing energy or a quality guarantee.',188:'Gaussian trough geometry is not a grout prescription; volume efficiency and gain are explicitly local synthetic assumptions; curvature excludes discrete joints.',189:'Isotropic undrained pore pressure is not a general shear rule; ideal grout geometry is not a treatment radius; surveyed heave and cavity fill are not all retained grout. Volume strain and vertical layer strain are distinguished.',190:'Diffusion length scaling explicitly holds dimensionless parameters fixed; actual drain spacing changes geometric ratio, smear and well resistance. Horizontal diffusion coefficient units, equivalent perimeter diameter, normally consolidated one-dimensional settlement and matched-gradient clogging comparison are explicit.',191:'Vacuum observations share pressure/state reference; total stress and combined net pore-pressure increments are separated.',192:'Empirical depth coefficient units, energy loss and nonuniform delivery are stated.',193:'Darcy applicability, toe/head load difference and unit-cell versus global effects are stated.',194:'Compatible CRR/CSR, one-dimensional strain and dragload accounting are stated.',195:'Wave direction, strain allocation, material curves and joint movement components are separated.',196:'Units 6 and 9 were corrected after review: underside uplift at fixed upper pressure is distinguished explicitly from constant net buoyancy of a fully submerged sealed fixed-volume box.',197:'Projection and friction exclude separate anchor effects; geometric criteria do not prove stability.',198:'Two-way timing, calibrated velocity, attenuation path and confirmation-versus-detection fractions are explicit.',199:'Ideal free-ring buckling, short/long-term modulus and full uniform Manning flow boundaries explicit.',200:'IR drop versus polarization and electrochemical efficiency versus material utilization are separated.'}
ledger=[]
env={n:getattr(math,n) for n in ['pi','sqrt','sin','cos','tan','exp','log10']};env['min']=min
for i,items in R.items():
 d=json.loads((P/f'b{i}.json').read_text());assert len(items)==len(d['units'])==10
 for j,(expression,published,decimals) in enumerate(items,1):
  value=eval(expression,{'__builtins__':{}},env)
  assert round(value,decimals)==published,(i,j,expression,value,published)
  ledger.append(dict(course=f'b{i}',unit=j,expression=expression,computed=value,published=published,decimalPlaces=decimals,model=d['units'][j-1]['model']))
output=dict(arithmeticPassed=True,courses=len(R),units=len(ledger),boundaryReview=notes,pendingCourses=[f'b{i}' for i in range(176,201) if i not in R],calculations=ledger)
(ROOT/'docs/CROSS_REVIEW_GROUND_V14.json').write_text(json.dumps(output,ensure_ascii=False,indent=2)+'\n')
print('PASS independent arithmetic:',len(R),'courses;',len(ledger),'models. Physical boundary notes retained separately.')
